"""World map canvas for plotting coordinates, with embedded map image."""

import base64
import io
import tkinter as tk
from PIL import Image, ImageTk

# Embedded world map PNG (equirectangular projection)
_MAP_B64 = ""


class MiniMap(tk.Canvas):
    """A world map canvas with an embedded equirectangular map image."""

    def __init__(self, parent, width=580, height=150, **kwargs):
        kwargs.setdefault("bg", "#C8E6F5")
        kwargs.setdefault("highlightthickness", 0)
        super().__init__(parent, width=width, height=height, **kwargs)
        self.map_width = width
        self.map_height = height
        self._point_ids = []
        self._load_map()
        self.bind("<Configure>", self._on_resize)

    def _load_map(self):
        """Decode embedded base64 map image."""
        img_data = base64.b64decode(_MAP_B64)
        pil_img = Image.open(io.BytesIO(img_data))
        self._orig_img = pil_img
        self._photo_img = ImageTk.PhotoImage(pil_img.resize(
            (self.map_width, self.map_height), Image.LANCZOS
        ))
        self._bg_img_id = self.create_image(0, 0, anchor="nw", image=self._photo_img)
        self.tag_lower(self._bg_img_id)

    def _on_resize(self, event):
        """Resize map image when canvas size changes."""
        w, h = event.width, event.height
        if w > 10 and h > 10:
            self.map_width = w
            self.map_height = h
            self._photo_img = ImageTk.PhotoImage(
                self._orig_img.resize((w, h), Image.LANCZOS)
            )
            self.itemconfig(self._bg_img_id, image=self._photo_img)
            for pid in self._point_ids:
                self.delete(pid)
            self._point_ids.clear()

    def _lonlat_to_xy(self, lon, lat):
        x = (lon + 180) / 360 * self.map_width
        y = (90 - lat) / 180 * self.map_height
        return x, y

    def clear_points(self):
        for pid in self._point_ids:
            self.delete(pid)
        self._point_ids.clear()

    def plot_point(self, lat, lon, color="#FF4444", label=""):
        x, y = self._lonlat_to_xy(lon, lat)
        if 0 <= x <= self.map_width and 0 <= y <= self.map_height:
            r = 5
            pid = self.create_oval(x - r, y - r, x + r, y + r,
                                   fill=color, outline="#880000", width=1.5, tags="point")
            self._point_ids.append(pid)
            if label:
                tid = self.create_text(x + 8, y - 8, text=label, fill="#222222",
                                       font=("Segoe UI", 8, "bold"), anchor="w", tags="point")
                self._point_ids.append(tid)

    def plot_batch(self, pairs):
        self.clear_points()
        for i, (lat, lon) in enumerate(pairs):
            if lat is not None and lon is not None:
                self.plot_point(lat, lon, color="#FF4444", label=str(i + 1))
            elif lat is not None:
                self.plot_point(lat, 0, color="#FF8800", label=str(i + 1) + "(?)")
            elif lon is not None:
                self.plot_point(0, lon, color="#FF8800", label=str(i + 1) + "(?)")
